from __future__ import absolute_import

from selenium.common.exceptions import StaleElementReferenceException, TimeoutException
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.common.utils import wait_for_operation_success
from taf.selenium.sbts_fsm3.pages import v23r3
from taf.selenium.sbts_fsm3.pages.modals import StartDiagnosticCheckModal
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel


class Diagnostic(v23r3.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._test_setup = TestSetupPage(driver)
        self._diagnostic_check = DiagnosticCheckPage(driver)

    @property
    def diagnostic_check(self):
        return self._diagnostic_check


class TestSetupPage(v23r3.diagnostic.TestSetupPage):
    def __init__(self, driver):
        super(TestSetupPage, self).__init__(driver)
        self._view_panel = TestSetupPageViewPanel(driver)


class TestSetupPageViewPanel(v23r3.diagnostic.TestSetupPageViewPanel):
    NR = "NR"
    ALL_NR_CELLS = "All NR cells"

    def __init__(self, driver):
        super(TestSetupPageViewPanel, self).__init__(driver)

    def configure_rf_diagnostic_test(self, activate, cell, bts_thresholds, bands_thresholds, timeout, technology='NR'):
        self.click_enabled_element((By.XPATH, self._TECHNOLOGY.format(technology.lower())), timeout)

        if technology == self.NR and "All" in cell:
            cell = self.ALL_NR_CELLS
        self.select_element_from_dropdown_list_by_text_and_click(cell,
                                                                 (By.XPATH, self._START_TEST_FOR_CELL_DROPDOWN_BUTTON),
                                                                 (By.XPATH, self._START_TEST_FOR_CELL_DROPDOWN_ITEM),
                                                                 timeout)
        self.configure_and_check_bts_thresholds(bts_thresholds, timeout)
        self._configure_bands_thresholds(bands_thresholds, timeout)

    def configure_statistics_diagnostic_test(self, activate, radio, timeout=60):
        self.select_element_from_dropdown_list_by_text_and_click(
            radio,
            (By.XPATH, self._START_STATISTICS_TEST_FOR_RADIO_DROPDOWN_BUTTON),
            (By.XPATH, self._START_STATISTICS_TEST_FOR_CELL_DROPDOWN_ITEM),
            timeout)


class DiagnosticCheckPage(NavigatablePage):
    _MENU_ROUTE_LIST = ["Diagnostic", "Diagnostic Check"]

    def __init__(self, driver):
        super(DiagnosticCheckPage, self).__init__(driver)
        self._view_panel = DiagnosticCheckPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def start_diagnostic_check(self, scope, timeout=60, **kwargs):
        return self._view_panel.start_diagnostic_check(scope, timeout, **kwargs)

    def get_report(self):
        return self._view_panel.get_report()


class DiagnosticCheckPageViewPanel(ViewPanel):
    _SCOPE_BUTTON = '//blocks-diagnostic-check-setup//*[label[contains(text(), "Scope")]]//p-dropdown'
    _SCOPE_OPTION = '//blocks-diagnostic-check-setup//*[label[contains(text(), "Scope")]]//p-dropdown//li'
    _ALLOW_SERVICE_IMPACT = '//blocks-diagnostic-check-setup//p-checkbox[label[text()="Allow service impact"]]'

    _BTS_CHECKPOINTS = '//blocks-diagnostic-check-setup//*[label[contains(text(), "Select BTS")]]//p-multiselect'
    _BTS_CHECKPOINTS_ALL = _BTS_CHECKPOINTS + '//*[contains(@class, "multiselect-header")]//*[@role="checkbox"]'
    _BTS_CHECKPOINTS_OPTIONS = _BTS_CHECKPOINTS + '//p-multiselectitem'

    _FETCHING_CHECKPOINTS = '//*[contains(text(), "Fetching check points succeeded")]'
    _RADIO_CHECKPOINTS = '//blocks-diagnostic-check-setup//*[label[contains(text(), "Select radio")]]//p-treeselect'
    _RADIO_TREE_CHECKS_ALL = ('//*[contains(@class, "p-treeselect-items-wrapper")]'
                              '//p-treenode[@ng-reflect-level="0"]/li/div/div')
    _RADIO_TITLES = _RADIO_TREE_CHECKS_ALL + '/following-sibling::span'
    _TREENODE = '//*[text()="{}"]/ancestor::p-treenode'
    _TREEITEM = '//*[text()="{}"]/ancestor::div[@role="treeitem"]'
    _RADIO_OPTIONS = '//*[text()="{}"]/ancestor::li//ul//li/div[@role="treeitem"]'
    _START_BUTTON = '//cem-operation-button//button[*[text()="Start"]]'
    _GET_REPORT_BUTTON = '//cem-operation-button//button[*[text()="Get Report"]]'
    _STARTING_STATUS = '//ot-instruction//*[contains(text(), "Diagnostic check is ongoing")]'
    _START_SUCCEEDED_STATUS = '//ot-instruction//*[contains(text(), "Diagnostic check succeeded")]'
    _GET_REPORT_STATUS = '//ot-instruction//*[text()="Getting report succeeded"]'
    _REPORT_EXPAN_ICON = '//*[@*="{}"]//span[contains(@class, "p-accordion-toggle-icon")]'
    _TITLE = '//*[@*="{}"]//table//thead//th'
    _BODY_TR = '//*[@*="{}"]//table//tbody//tr'
    NO_DATA_AVAILABLE = 'No data available'
    FULL_DIAGNOSTIC_CHECK = "Full diagnostic check"
    CUSTOMIZED_DIAGNOSTIC_CHECK = "Customized diagnostic check"

    def __init__(self, driver):
        super(DiagnosticCheckPageViewPanel, self).__init__(driver)

    def start_diagnostic_check(self, scope, timeout=60, **kwargs):
        self.wait_for_enable((By.XPATH, self._SCOPE_BUTTON), timeout)
        self.select_element_from_dropdown_list_by_text_and_click(scope,
                                                                 (By.XPATH, self._SCOPE_BUTTON),
                                                                 (By.XPATH, self._SCOPE_OPTION),
                                                                 timeout)
        self.wait_for_enable((By.XPATH, self._SCOPE_BUTTON), timeout)

        all_service_impact = None
        if self.FULL_DIAGNOSTIC_CHECK == scope:
            all_service_impact = kwargs.get('allow_service_impact', False)
            self.select_checkbox_by_specified_status(all_service_impact,
                                                     self._ALLOW_SERVICE_IMPACT + '//input',
                                                     self._ALLOW_SERVICE_IMPACT)

        elif self.CUSTOMIZED_DIAGNOSTIC_CHECK == scope:
            bts_checkpoints = kwargs.get('bts_checkpoints', [])
            self._select_bts_checkpoints(bts_checkpoints, timeout)

            radio_checkpoints = kwargs.get('radio_checkpoints', [])
            self.rst = False
            self._select_radio_checkpoints(radio_checkpoints, timeout)

        self.click_enabled_element((By.XPATH, self._START_BUTTON), timeout)

        if self.FULL_DIAGNOSTIC_CHECK == scope and all_service_impact:
            check_modal = StartDiagnosticCheckModal(self.driver)
            check_modal.wait_until_diagnostic_check_modal_appear(timeout)
            check_modal.start()
            self.wait_for_visibility(self._STARTING_STATUS, timeout)
            return

        if self.CUSTOMIZED_DIAGNOSTIC_CHECK == scope and (not radio_checkpoints or self.rst):
            check_modal = StartDiagnosticCheckModal(self.driver)
            check_modal.wait_until_diagnostic_check_modal_appear(5)
            check_modal.start()

        self.wait_for_visibility(self._STARTING_STATUS, timeout)
        self.wait_for_invisibility(self._STARTING_STATUS, timeout)
        self.wait_for_visibility(self._START_SUCCEEDED_STATUS, timeout)
        return self.get_text_by_xpath(self._START_SUCCEEDED_STATUS)

    def _select_bts_checkpoints(self, bts_checkpoints, timeout=60):
        try:
            self.wait_for_visibility(self._FETCHING_CHECKPOINTS, 10)
        except TimeoutException:
            pass

        bts_checkpoints_status = self.get_attribute_by_xpath(self._BTS_CHECKPOINTS, "ng-reflect-is-disabled") == "true"
        if bts_checkpoints_status and bts_checkpoints:
            raise AttributeError("No valid BTS check points.")

        if bts_checkpoints_status and not bts_checkpoints:
            return

        self.click_enabled_element((By.XPATH, self._BTS_CHECKPOINTS), timeout)
        all_selected = self.driver.find_element_by_xpath(self._BTS_CHECKPOINTS_ALL).get_attribute('aria-checked')
        all_selected = all_selected == 'true'

        if not bts_checkpoints and not all_selected:
            self.click_enabled_element((By.XPATH, self._BTS_CHECKPOINTS_ALL), timeout)
        elif not bts_checkpoints and all_selected:
            pass
        else:
            self._choose_value_if_checkbox_exist(self._BTS_CHECKPOINTS_OPTIONS, bts_checkpoints, 'ng-reflect-selected')
        self.click_enabled_element((By.XPATH, self._BTS_CHECKPOINTS), timeout)

    def _select_radio_checkpoints(self, radio_checkpoints, timeout=60):
        radio_checkpoints_status = self.get_attribute_by_xpath(self._RADIO_CHECKPOINTS,
                                                               "ng-reflect-is-disabled") == "true"
        if radio_checkpoints_status and radio_checkpoints:
            raise AttributeError("No valid radio check points.")

        if radio_checkpoints_status and not radio_checkpoints:
            return

        self.click_enabled_element((By.XPATH, self._RADIO_CHECKPOINTS), timeout)
        if not radio_checkpoints:
            self._select_all_radio_checkpoints()
        else:
            self._select_radio_checkpoints_by_input(radio_checkpoints, timeout)
        self.click_enabled_element((By.XPATH, self._RADIO_CHECKPOINTS), timeout)

    def _select_all_radio_checkpoints(self):
        for index, _ in enumerate(self.driver.find_elements_by_xpath(self._RADIO_TREE_CHECKS_ALL)):
            elem = self.driver.find_elements_by_xpath(self._RADIO_TREE_CHECKS_ALL)[index]
            if elem.get_attribute('aria-checked') == 'false':
                self._scroll_elem_into_view(elem)
                elem = self.driver.find_elements_by_xpath(self._RADIO_TREE_CHECKS_ALL)[index]
                self.driver.execute_script('arguments[0].click();', elem)

    def _select_radio_checkpoints_by_input(self, radio_checkpoints, timeout=60):  # noqa: C901
        radio_titles = [elem.text.strip() for elem in self.driver.find_elements_by_xpath(self._RADIO_TITLES)]
        rmods = list(radio_checkpoints.keys())

        for radio_title in radio_titles:
            if radio_title not in rmods:
                radio_checkpoints[radio_title] = []

        for rmod_name, checkpoint in radio_checkpoints.items():
            for check in checkpoint:
                if "(RST)" in check:
                    self.rst = True
            tree_item_xpath = self._TREEITEM.format(rmod_name)
            expand_status = self._get_element_attribute_by_xpath(tree_item_xpath, "aria-expanded") == "true"
            if not expand_status:
                self.click_enabled_element((By.XPATH, self._TREEITEM.format(rmod_name) + '//button'), timeout)
            self._choose_value_if_checkbox_exist(self._RADIO_OPTIONS.format(rmod_name),
                                                 checkpoint,
                                                 'aria-selected')
            button_xpath = self._TREEITEM.format(rmod_name) + '//button'
            self.driver.execute_script('arguments[0].click();', self.driver.find_element_by_xpath(button_xpath))

    def _choose_value_if_checkbox_exist(self, check_box_xpath, value, attribute):
        value = [str(item) for item in value]
        for index, _ in enumerate(self.driver.find_elements_by_xpath(check_box_xpath)):
            self._scroll_elem_into_view(self.driver.find_elements_by_xpath(check_box_xpath)[index])
            is_checked = self._get_element_attribute_by_xpath(check_box_xpath, attribute, index) == "true"
            element_text = self._get_element_text_by_xpath(check_box_xpath, index)
            if (not is_checked and element_text in value) or (is_checked and element_text not in value):
                self._click_element_by_multiple_xpath_and_index(
                    [check_box_xpath, './/div[contains(@class, "p-checkbox-box")]'],
                    [index, 0]
                )

    @wait_for_operation_success(3)
    def _get_element_attribute_by_xpath(self, xpath, attribute_name, index=0):
        elem = self.driver.find_elements_by_xpath(xpath)[index]
        return elem.get_attribute(attribute_name)

    @wait_for_operation_success(3)
    def _get_element_text_by_xpath(self, xpath, index=0):
        return self.driver.find_elements_by_xpath(xpath)[index].text

    @wait_for_operation_success(3)
    def _click_element_by_multiple_xpath_and_index(self, xpath, indexes):
        elem = None
        for index, _ in enumerate(indexes):
            if not elem:
                elem = self.driver.find_elements_by_xpath(xpath[index])[indexes[index]]
            else:
                elem = elem.find_elements_by_xpath(xpath[index])[indexes[index]]
        self.driver.execute_script('arguments[0].click();', elem)

    def get_report(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._GET_REPORT_BUTTON), timeout)
        self.wait_for_visibility((By.XPATH, self._GET_REPORT_STATUS), timeout)
        bts_diagnostic_check_report = self._get_bts_diagnostic_check_report('BTS diagnostic check report')
        ru_diagnostic_check_report = self._get_bts_diagnostic_check_report('RU diagnostic check report')
        return {"BTS diagnostic check report": bts_diagnostic_check_report,
                "RU diagnostic check report": ru_diagnostic_check_report}

    def _get_bts_diagnostic_check_report(self, module):  # noqa: C901
        expand_element = self.driver.find_element_by_xpath(self._REPORT_EXPAN_ICON.format(module))
        orientation = expand_element.get_attribute("ng-reflect-ng-class")
        if "down" in orientation:
            expand_element.click()

        title = [elem.text for elem in self.driver.find_elements_by_xpath(self._TITLE.format(module))]

        total_trs = len(self.driver.find_elements_by_xpath(self._BODY_TR.format(module)))
        content = []
        for index in range(1, total_trs + 1):
            content.append(self._get_content_from_table_line(self._BODY_TR.format(module) + '[{}]//td'.format(index)))

        num = len(content[0])
        if len(content[0]) == 1 and content[0][0] == self.NO_DATA_AVAILABLE:
            content[0] = content[0] * len(title)

        for index, item in enumerate(content):
            if len(item) == num:
                first_filed = content[index][0]
            elif len(item) < num:
                item.insert(0, first_filed)

        outcome = []
        for item in content:
            outcome.append(dict(zip(title, item)))
        return outcome

    @wait_for_operation_success(3, StaleElementReferenceException)
    def _get_content_from_table_line(self, locator):
        content = []
        for elem in self.driver.find_elements_by_xpath(locator):
            content.append(elem.text)
        return content
